import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem95 nao converte codigo ou publicidade em especificacoes comprovadas',()=>{for(const [id,titulo] of [['mlMLB4031468281','Tênis Masculino Casual Sapatenis Novo Lançamento Conforto'],['mlMLB4147473207','Tênis Feminino Esportivo Actvitta Super Leve Macio Corrida']]){const p={id,titulo,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.equal(x.titulo,titulo);assert.deepEqual(correctProductData(x),x);assert.match(x.comentario,/anúncio do vendedor, não um código de catálogo confirmado/);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.pros,/peso medido|conforto comprovado|lançado em 2026|catálogo confirmado/i);}});
